import { createElement } from 'react'
import type { ReactElement, SVGProps } from 'react'

/* GNOME 的符号图标：取自 adwaita-icon-theme（Adwaita/symbolic，CC-BY-SA 3.0）和 GNOME 设计团队的
   Icon Development Kit（CC0），导出名沿用界面里原有的图标名。符号图标在 16px 网格上绘制，
   界面里一律按 16px 显示，只有状态页一类的大图标才用更大的尺寸。 */

export type IconProps = Omit<SVGProps<SVGSVGElement>, 'children'> & { size?: number }
export type Icon = ((props: IconProps) => ReactElement) & { displayName: string }

function icon(name: string, body: string): Icon {
  const Symbolic = ({ size = 16, ...props }: IconProps) => {
    const px = size < 24 ? 16 : size
    return createElement('svg', {
      width: px,
      height: px,
      viewBox: '0 0 16 16',
      fill: 'currentColor',
      'aria-hidden': true,
      focusable: false,
      ...props,
      dangerouslySetInnerHTML: { __html: body },
    })
  }
  Symbolic.displayName = `${name}-symbolic`
  return Symbolic
}

